WITH ranked AS (SELECT *, RANK() OVER (PARTITION BY location ORDER BY budget DESC) AS rn FROM departments QUALIFY rn = 1), metrics AS (SELECT id, dept_name, location, LAG(budget) OVER (PARTITION BY location, dept_name ORDER BY rn, id) AS prev_budget, LEAD(budget) OVER (PARTITION BY location, dept_name ORDER BY rn, id) AS next_budget, ROW_NUMBER() OVER (PARTITION BY location, dept_name ORDER BY rn, id) AS row_seq FROM ranked), with_windows AS (SELECT *, STDDEV_SAMP(next_budget) OVER (PARTITION BY dept_name, location) AS dept_name_stddev_samp_next_budget, ROW_NUMBER() OVER (PARTITION BY location ORDER BY prev_budget, id) AS event_seq, MIN(prev_budget) OVER (PARTITION BY location) AS location_min_prev_budget, NTILE(10) OVER (PARTITION BY dept_name ORDER BY row_seq DESC, id) AS row_seq_bucket, LEAD(prev_budget, 2) OVER (ORDER BY next_budget, id) AS next_prev_budget FROM metrics WHERE dept_name IN ('Engineering', 'Sales')), with_windows_departments AS (SELECT id, dept_name, prev_budget, row_seq, dept_name_stddev_samp_next_budget, location_min_prev_budget, row_seq_bucket, next_prev_budget, STDDEV_SAMP(row_seq) OVER (PARTITION BY dept_name) AS dept_name_stddev_samp_row_seq, PERCENT_RANK() OVER (PARTITION BY location ORDER BY location_min_prev_budget DESC) AS location_min_prev_budget_percent_rank FROM with_windows), with_windows_departments_2 AS (SELECT *, LEAD(dept_name_stddev_samp_next_budget, 1) OVER w_hist AS next_dept_name_stddev_samp_next_budget, ROUND(row_seq / SUM(row_seq) OVER (PARTITION BY dept_name), 4) AS row_seq_share, AVG(location_min_prev_budget_percent_rank) OVER w_part AS location_min_prev_budget_percent_rank_avg_2, FIRST_VALUE(dept_name_stddev_samp_row_seq, TRUE) OVER w_part_2 AS first_known_dept_name_stddev_samp_row_seq, NTILE(5) OVER (ORDER BY location_min_prev_budget_percent_rank, id) AS location_min_prev_budget_percent_rank_bucket FROM with_windows_departments WINDOW w_hist AS (PARTITION BY dept_name ORDER BY location_min_prev_budget, id), w_part AS (ORDER BY row_seq_bucket, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), w_part_2 AS (PARTITION BY dept_name ORDER BY next_prev_budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, dept_name, dept_name_stddev_samp_next_budget, location_min_prev_budget, row_seq_bucket, dept_name_stddev_samp_row_seq, location_min_prev_budget_percent_rank, CASE WHEN dept_name RLIKE '^(HR|Marketing)$' THEN 'EXTENDED' WHEN dept_name RLIKE '^(Engineering|Sales)$' THEN 'GROUP_A' ELSE 'CORE' END AS dept_name_zone FROM with_windows_departments_2 ORDER BY location_min_prev_budget
